185		}
186		decisions := drainAudit(t, s, contestOrg, AuditDecision, "")
187		if len(decisions) != 1 {
188			t.Fatalf("[%s wins] decision records = %d, want 1", winner, len(decisions))
189		}
190		dr := decisions[0]
191		if dr.Seq != 4 || !reflect.DeepEqual(dr.Decision.Decision, d) ||
192			!reflect.DeepEqual(dr.Decision.Request, probe) {
193			t.Fatalf("[%s wins] saved decision = %+v, want %+v for request %+v", winner, dr.Decision, d, probe)
194		}
195		rechecked, err := s.RecheckDecision(contestOrg, dr.Seq)
196		if err != nil {
197			t.Fatalf("[%s wins] RecheckDecision: %v", winner, err)
198		}
199		if !reflect.DeepEqual(rechecked, d) {
200			t.Fatalf("[%s wins] recheck = %+v, want %+v", winner, rechecked, d)
201		}
202	
203		// Historical versions still review independently and were not rewritten
204		// by the contention.
205		if d1 := s.Review(contestOrg, 1, probe); !reflect.DeepEqual(d1, evaluate(probe, v1, 1)) {
206			t.Fatalf("[%s wins] review v1 drifted: %+v", winner, d1)
207		}
208		if d2 := s.Review(contestOrg, 2, probe); !reflect.DeepEqual(d2, evaluate(probe, v2, 2)) {
209			t.Fatalf("[%s wins] review v2 drifted: %+v", winner, d2)
210		}
211	
212		// Final chain (change + decision) still verifies in full.
213		exported, cp, err = s.AuditExport(contestOrg, 0)
214		if err != nil {
215			t.Fatalf("[%s wins] final AuditExport: %v", winner, err)
216		}
217		if len(exported) != 4 {
218			t.Fatalf("[%s wins] final records = %d, want 4", winner, len(exported))
219		}
220		if err := VerifyAudit(contestOrg, exported, cp); err != nil {
221			t.Fatalf("[%s wins] final chain does not verify: %v", winner, err)
222		}
223	}
224	
225	// TestPublishBeatsRollbackOnSameExpectedVersion pins the publish-winning
226	// ordering: the publish runs first while both callers still claim current
227	// version 2; the following rollback must be rejected as a conflict.
228	func TestPublishBeatsRollbackOnSameExpectedVersion(t *testing.T) {
229		s, v1, v2, candidate := setupContendedStore(t)
230	
231		newVersion, err := s.Publish(contestOrg, 2, candidate)
232		if err != nil || newVersion != 3 {
